/** mcq-feedback 4.0 - learner runtime with shared Seleda LMS tracking */
var $mcqfeedback={
 runtimeVersion:'seleda-mcq-4.5.1',
 ideviceClass:'mcqfIdeviceContent',autoObserver:null,
 esc:function(v){return String(v==null?'':v).replace(/&/g,'&amp;').replace(/"/g,'&quot;').replace(/</g,'&lt;').replace(/>/g,'&gt;');},
 tracking:function(d,passing){var t=d.mcqTracking||{},mode=t.mode==='off'||t.mode==='completion'?t.mode:'graded',policy=t.scorePolicy==='best'||t.scorePolicy==='first'?t.scorePolicy:'latest';return{mode:mode,required:t.required!==false,weight:Math.min(100,Math.max(1,parseFloat(t.weight)||1)),passingScore:passing,scorePolicy:policy,detailedInteractions:mode==='graded'&&t.detailedInteractions!==false,resume:false};},
 settings:function(d){var s=d.mcqSettings||{},passing=Math.min(100,Math.max(0,parseFloat(s.passingScore)||50));return{shuffleQuestions:!!s.shuffleQuestions,shuffleChoices:!!s.shuffleChoices,feedbackTiming:s.feedbackTiming==='delayed'?'delayed':'immediate',maxAttempts:Math.max(0,parseInt(s.maxAttempts,10)||0),passingScore:passing,showCorrectness:s.showCorrectness!==false,showAnswers:s.showAnswers!==false,tracking:this.tracking(d,passing)};},
 reportDefinition:function(d){return{schema:1,blockType:'mcq-feedback',title:'Multiple Choice (per-answer feedback)',items:(d.mcqQuestions||[]).map(function(q,qi){return{id:q.id||('q'+qi),type:'choice',prompt:q.text||'',options:(q.choices||[]).map(function(c,ci){return{id:c.id||('c'+ci),label:c.text||''};})};})};},
 renderView:function(data,accessibility,template){var d=data||{},s=this.settings(d),id=d.ideviceId||('mcqf-'+Math.random().toString(36).slice(2)),html='<div class="'+this.ideviceClass+'" data-settings="'+this.esc(JSON.stringify(s))+'" data-instance="'+this.esc(id)+'" data-timhirt-reporting="'+this.esc(JSON.stringify(this.reportDefinition(d)))+'">';if(d.mcqInstructions)html+='<div class="mcqf-instructions">'+d.mcqInstructions+'</div>';html+='<div class="mcqf-questions">';(d.mcqQuestions||[]).forEach(function(q,qi){var qid=q.id||('q'+qi);html+='<section class="mcqf-question" data-qid="'+$mcqfeedback.esc(qid)+'" data-qtype="'+(q.type==='multiple'?'multiple':'single')+'"><div class="mcqf-question-text"><span class="mcqf-number">'+(qi+1)+'.</span> '+(q.text||'')+'</div><ul class="mcqf-choice-list">';(q.choices||[]).forEach(function(c,ci){var cid=c.id||('c'+ci),type=q.type==='multiple'?'checkbox':'radio';html+='<li class="mcqf-choice" data-cid="'+$mcqfeedback.esc(cid)+'" data-correct="'+(c.correct?'1':'0')+'"><label class="mcqf-choice-label"><input type="'+type+'" name="mcqf-'+$mcqfeedback.esc(id)+'-'+$mcqfeedback.esc(qid)+'"><span class="mcqf-choice-text">'+(c.text||'')+'</span><span class="mcqf-result-label" aria-hidden="true"></span></label><div class="mcqf-feedback" tabindex="-1" hidden>'+(c.feedback||'')+'</div></li>';});html+='</ul><div class="mcqf-actions"><button type="button" class="mcqf-submit">Submit answer</button><div class="mcqf-status" role="status" aria-live="polite" tabindex="-1"></div></div></section>';});html+='</div><div class="mcqf-quiz-actions"><button type="button" class="mcqf-finish">Finish quiz</button><button type="button" class="mcqf-retry" hidden>Try again</button><button type="button" class="mcqf-solutions" hidden>Show solutions</button><div class="mcqf-summary" role="status" aria-live="polite" tabindex="-1"></div></div></div>';return template.replace('{content}',html);},
 parseSettings:function(root){try{return JSON.parse(root.getAttribute('data-settings')||'{}');}catch(e){return{};}},
 shuffle:function(parent,selector){var a=Array.prototype.slice.call(parent.querySelectorAll(':scope > '+selector));for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t;}a.forEach(function(x){parent.appendChild(x);});},
 renumber:function(root){root.querySelectorAll('.mcqf-question').forEach(function(q,i){q.querySelector('.mcqf-number').textContent=(i+1)+'.';});},
 startAttempt:function(root){var s=this.parseSettings(root);root.dataset.finished='0';root.dataset.solutions='0';root.querySelector('.mcqf-solutions').hidden=true;root.querySelector('.mcqf-solutions').disabled=false;root.querySelector('.mcqf-solutions').textContent='Show solutions';root.dataset.confirmFinish='0';root.querySelectorAll('.mcqf-question').forEach(function(q){q.dataset.submitted='0';q.classList.remove('is-correct','is-incorrect','is-partial');q.querySelectorAll('input').forEach(function(i){i.checked=false;i.disabled=false;});q.querySelectorAll('.mcqf-choice').forEach(function(c){c.classList.remove('is-selected','is-correct','is-incorrect','is-answer');c.querySelector('.mcqf-result-label').textContent='';});q.querySelector('.mcqf-status').textContent='';});root.querySelectorAll('.mcqf-feedback').forEach(function(f){f.hidden=true;});if(s.shuffleQuestions)this.shuffle(root.querySelector('.mcqf-questions'),'.mcqf-question');if(s.shuffleChoices)root.querySelectorAll('.mcqf-choice-list').forEach(function(l){$mcqfeedback.shuffle(l,'.mcqf-choice');});this.renumber(root);root.querySelector('.mcqf-summary').textContent='';root.querySelector('.mcqf-finish').hidden=false;root.querySelector('.mcqf-retry').hidden=true;},
 scoreQuestion:function(q){var cs=Array.prototype.slice.call(q.querySelectorAll('.mcqf-choice')),good=cs.filter(function(c){return c.dataset.correct==='1';}),bad=cs.filter(function(c){return c.dataset.correct!=='1';}),sg=good.filter(function(c){return c.querySelector('input').checked;}).length,sb=bad.filter(function(c){return c.querySelector('input').checked;}).length;if(q.dataset.qtype!=='multiple')return sg===1?1:0;return Math.max(0,(sg/good.length)-(bad.length?sb/bad.length:0));},
 labelFor:function(score){if(score>=.999)return'Correct';if(score<=.001)return'Incorrect';return'Partially correct';},
 revealQuestion:function(q,final){var s=this.parseSettings(q.closest('.'+this.ideviceClass)),score=this.scoreQuestion(q),label=this.labelFor(score),status=q.querySelector('.mcqf-status'),revealAnswers=s.showAnswers&&q.closest('.'+this.ideviceClass).dataset.solutions==='1',withholdChoices=q.dataset.qtype==='multiple'&&score<.999&&!revealAnswers;q.classList.remove('is-correct','is-incorrect','is-partial');if(s.showCorrectness)q.classList.add(score>=.999?'is-correct':score<=.001?'is-incorrect':'is-partial');q.querySelectorAll('.mcqf-choice').forEach(function(c){var selected=c.querySelector('input').checked,correct=c.dataset.correct==='1';c.classList.toggle('is-selected',selected);c.classList.remove('is-correct','is-incorrect','is-answer');if(!withholdChoices&&s.showCorrectness&&(selected||revealAnswers)){c.classList.toggle('is-correct',selected&&correct);c.classList.toggle('is-incorrect',selected&&!correct);c.classList.toggle('is-answer',revealAnswers&&correct&&!selected);}c.querySelector('.mcqf-result-label').textContent=withholdChoices?'':selected?(correct?'Correct':'Incorrect'):(revealAnswers&&correct?'Correct answer':'');var f=c.querySelector('.mcqf-feedback');f.hidden=withholdChoices||!((selected||revealAnswers&&correct)&&(s.feedbackTiming==='immediate'||final));});status.textContent=label+'. Question score: '+Math.round(score*100)+'%.';q.dataset.submitted='1';if(!final)status.focus();return score;},
 submitQuestion:function(q){var root=q.closest('.'+this.ideviceClass),s=this.parseSettings(root);if(root.dataset.finished==='1')return;if(!q.querySelector('input:checked')){var st=q.querySelector('.mcqf-status');st.textContent='Select at least one answer before submitting.';st.focus();return;}q.dataset.submitted='1';root.dataset.confirmFinish='0';if(s.feedbackTiming==='immediate')this.revealQuestion(q,false);else{var status=q.querySelector('.mcqf-status');status.textContent='Answer saved. Feedback will appear after you finish the quiz.';status.focus();}},
 interactionFor:function(q,index){var selected=[],correct=[];q.querySelectorAll('.mcqf-choice').forEach(function(c){var id=c.dataset.cid||'',input=c.querySelector('input');if(input&&input.checked)selected.push(id);if(c.dataset.correct==='1')correct.push(id);});var qscore=this.scoreQuestion(q);return{id:(q.dataset.qid||('q'+index)),type:'choice',response:selected.join(','),correctResponse:correct.join(','),result:qscore>=.999?'correct':qscore<=.001?'wrong':qscore,weighting:1};},
 bindTracking:function(root){var s=this.parseSettings(root);if(!s.tracking||s.tracking.mode==='off'||!window.SeledaLMS||typeof window.SeledaLMS.register!=='function')return;try{root._timhirtLms=window.SeledaLMS.register({element:root,type:'mcq-feedback',defaultMode:'graded',settings:s.tracking});}catch(e){if(window.console)console.warn('[mcq-feedback] Seleda LMS registration failed',e);}},
 reportTracking:function(root,score,passed,questions){var s=this.parseSettings(root),handle=root._timhirtLms;if(handle){try{handle.report({completed:true,score:score,incrementAttempt:true,resume:{finished:1,score:score,passed:passed?1:0}});if(handle.settings&&handle.settings.detailedInteractions){questions.forEach(function(q,i){handle.interaction($mcqfeedback.interactionFor(q,i));});}return;}catch(e){if(window.console)console.warn('[mcq-feedback] Seleda LMS report failed; trying legacy SCORM fallback',e);}}if(!s.tracking||s.tracking.mode!=='off')this.reportScoreLegacy(score,passed);},
 finish:function(root){if(root.dataset.finished==='1')return;var qs=Array.prototype.slice.call(root.querySelectorAll('.mcqf-question')),unanswered=qs.filter(function(q){return!q.querySelector('input:checked');}).length,summary=root.querySelector('.mcqf-summary');if(unanswered&&root.dataset.confirmFinish!=='1'){root.dataset.confirmFinish='1';summary.textContent=unanswered+' unanswered question'+(unanswered===1?' remains. ':'s remain. ')+'Click Finish quiz again to submit anyway.';summary.focus();return;}var total=0;qs.forEach(function(q){total+=$mcqfeedback.revealQuestion(q,true);q.querySelectorAll('input').forEach(function(i){i.disabled=true;});});var score=qs.length?Math.round(total/qs.length*100):0,s=this.parseSettings(root),passed=score>=s.passingScore;root.dataset.finished='1';root.dataset.attempts=String((parseInt(root.dataset.attempts,10)||0)+1);summary.textContent=(passed?'Passed':'Not passed')+'. Score: '+score+'%. Passing score: '+s.passingScore+'%. Attempt '+root.dataset.attempts+(s.maxAttempts?' of '+s.maxAttempts:'')+'.';root.querySelector('.mcqf-finish').hidden=true;root.querySelector('.mcqf-solutions').hidden=!s.showAnswers;var retry=root.querySelector('.mcqf-retry');retry.hidden=!!(s.maxAttempts&&parseInt(root.dataset.attempts,10)>=s.maxAttempts);summary.focus();this.reportTracking(root,score,passed,qs);},
 showSolutions:function(root){if(root.dataset.finished!=='1'||!this.parseSettings(root).showAnswers||root.dataset.solutions==='1')return;root.dataset.solutions='1';root.querySelectorAll('.mcqf-question').forEach(function(q){$mcqfeedback.revealQuestion(q,true);});var button=root.querySelector('.mcqf-solutions');button.textContent='Solutions shown';button.disabled=true;},
 findRawScormApi:function(){function findRaw(w){var n=0;while(w&&n<20){try{if(w.API)return w.API;if(!w.parent||w.parent===w)break;w=w.parent;}catch(e){break;}n++;}return null;}var raw=findRaw(window);try{if(!raw&&window.top&&window.top.opener)raw=findRaw(window.top.opener);if(!raw&&window.opener)raw=findRaw(window.opener);}catch(e){}return raw;},
 reportScoreLegacy:function(score,passed){try{var status=passed?'passed':'failed',saved=false,raw=this.findRawScormApi();if(raw&&typeof raw.LMSSetValue==='function'){var tryWrite=function(){var a=raw.LMSSetValue('cmi.core.score.min','0'),b=raw.LMSSetValue('cmi.core.score.max','100'),c=raw.LMSSetValue('cmi.core.score.raw',String(score)),d=raw.LMSSetValue('cmi.core.lesson_status',status),ok=String(d).toLowerCase()==='true';if(typeof raw.LMSCommit==='function')ok=String(raw.LMSCommit('')).toLowerCase()==='true'&&ok;return ok;};saved=tryWrite();if(!saved&&typeof raw.LMSGetLastError==='function'&&String(raw.LMSGetLastError())==='301'&&typeof raw.LMSInitialize==='function'){try{raw.LMSInitialize('');}catch(e){}saved=tryWrite();}if(saved)return;}if(window.pipwerks&&window.pipwerks.SCORM){var p=window.pipwerks.SCORM;if(typeof p.init==='function')try{p.init();}catch(e){}var setOk=false;if(typeof p.set==='function'){var p1=p.set('cmi.core.score.min','0'),p2=p.set('cmi.core.score.max','100'),p3=p.set('cmi.core.score.raw',String(score)),p4=p.set('cmi.core.lesson_status',status);setOk=String(p4).toLowerCase()==='true'||p4===true;}if(typeof p.save==='function')try{saved=!!p.save()&&setOk;}catch(e){}if(saved)return;}var api=window.scorm||(window.$mcqfeedback&&$mcqfeedback.mScorm);if(api){var ok=false;if(typeof api.init==='function')try{api.init();}catch(e){}if(typeof api.SetScoreMin==='function')api.SetScoreMin(0);if(typeof api.SetScoreMax==='function')api.SetScoreMax(100);if(typeof api.SetScoreRaw==='function')api.SetScoreRaw(score);if(typeof api.SetStatus==='function')ok=String(api.SetStatus(status)).toLowerCase()==='true';else if(typeof api.set==='function')ok=String(api.set('cmi.core.lesson_status',status)).toLowerCase()==='true';if(typeof api.save==='function')try{ok=!!api.save()&&ok;}catch(e){}if(ok)return;}if(window.console)console.warn('[mcq-feedback] SCORM reporting did not reach an active LMS API.');}catch(e){if(window.console)console.warn('[mcq-feedback] Legacy SCORM score could not be saved',e);}},
 diagnostics:function(){var raw=this.findRawScormApi(),status='',score='',err='';try{if(raw&&typeof raw.LMSGetValue==='function'){status=raw.LMSGetValue('cmi.core.lesson_status');score=raw.LMSGetValue('cmi.core.score.raw');if(typeof raw.LMSGetLastError==='function')err=raw.LMSGetLastError();}}catch(e){err=String(e&&e.message||e);}return{timhirtLms:!!window.SeledaLMS,pipwerks:!!(window.pipwerks&&window.pipwerks.SCORM),scormAlias:!!window.scorm,rawApi:!!raw,status:status,score:score,lastError:err,frame:window===window.top?'top':'iframe'};},
 bindRoot:function(root){if(root.dataset.mcqfBound==='1')return;root.dataset.mcqfBound='1';root.dataset.attempts='0';this.bindTracking(root);root.addEventListener('click',function(e){var q=e.target.closest('.mcqf-question');if(e.target.closest('.mcqf-submit')&&q)$mcqfeedback.submitQuestion(q);else if(e.target.closest('.mcqf-finish'))$mcqfeedback.finish(root);else if(e.target.closest('.mcqf-solutions'))$mcqfeedback.showSolutions(root);else if(e.target.closest('.mcqf-retry'))$mcqfeedback.startAttempt(root);});root.addEventListener('change',function(e){if(!e.target.matches('.mcqf-choice input'))return;var q=e.target.closest('.mcqf-question');q.dataset.submitted='0';root.dataset.confirmFinish='0';var s=$mcqfeedback.parseSettings(root);if(s.feedbackTiming==='immediate'){q.classList.remove('is-correct','is-incorrect','is-partial');q.querySelectorAll('.mcqf-choice').forEach(function(c){c.classList.remove('is-selected','is-correct','is-incorrect','is-answer');c.querySelector('.mcqf-feedback').hidden=true;c.querySelector('.mcqf-result-label').textContent='';});q.querySelector('.mcqf-status').textContent='';}});this.startAttempt(root);},
 renderBehaviour:function(){document.querySelectorAll('.'+this.ideviceClass).forEach(function(r){$mcqfeedback.bindRoot(r);});},init:function(){},
 startAutoInit:function(){this.renderBehaviour();if(!this.autoObserver&&typeof MutationObserver!=='undefined'&&document.body){this.autoObserver=new MutationObserver(function(){$mcqfeedback.renderBehaviour();});this.autoObserver.observe(document.body,{childList:true,subtree:true});}}
};
(function(){function go(){$mcqfeedback.startAutoInit();}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',go);else go();})();

